import { GalleryModel } from './solution';

function eq(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) throw new Error(message + ': ' + JSON.stringify(actual));
}
function throwsType(fn: () => unknown, message: string): void {
  try { fn(); } catch (error) { if (error instanceof TypeError) return; throw error; }
  throw new Error(message);
}

const input = [' first ', 'second', ' third '];
const gallery = new GalleryModel(input);
input[0] = 'changed';
input.push('fourth');
eq(gallery.snapshot(), { image: 'first', index: 0, tab: 'summary', images: ['first', 'second', 'third'] }, 'construction trims, detaches, and starts correctly');

gallery.next();
eq(gallery.snapshot().image, 'second', 'next advances');
gallery.next();
eq(gallery.snapshot().image, 'third', 'next reaches final image');
gallery.next();
eq(gallery.snapshot().image, 'first', 'next wraps to first');
gallery.previous();
eq(gallery.snapshot().image, 'third', 'previous wraps to final');
gallery.previous();
eq(gallery.snapshot().image, 'second', 'previous moves backward');
gallery.selectTab('notes');
eq(gallery.snapshot().tab, 'notes', 'notes tab selected');
gallery.selectTab('owner');
eq(gallery.snapshot().tab, 'owner', 'owner tab selected');

const snap: any = gallery.snapshot();
snap.image = 'changed';
snap.index = 99;
snap.tab = 'summary';
snap.images[0] = 'mutated';
snap.images.push('extra');
eq(gallery.snapshot(), { image: 'second', index: 1, tab: 'owner', images: ['first', 'second', 'third'] }, 'snapshot is detached');

const single = new GalleryModel([' only ']);
single.next();
eq(single.snapshot().image, 'only', 'single-image next wraps safely');
single.previous();
eq(single.snapshot().image, 'only', 'single-image previous wraps safely');

const emptyInput: string[] = [];
throwsType(() => new GalleryModel(emptyInput), 'empty gallery rejected');
eq(emptyInput, [], 'empty input unchanged on failure');
const blankInput = ['valid', '   '];
const blankBefore = JSON.stringify(blankInput);
throwsType(() => new GalleryModel(blankInput), 'blank image rejected');
eq(JSON.stringify(blankInput), blankBefore, 'blank input unchanged on failure');
const duplicateInput = [' same ', 'same'];
const duplicateBefore = JSON.stringify(duplicateInput);
throwsType(() => new GalleryModel(duplicateInput), 'duplicate after trimming rejected');
eq(JSON.stringify(duplicateInput), duplicateBefore, 'duplicate input unchanged on failure');

